define([],function(){'use strict';function setReactionButtons(playing){var root=document.querySelector('.videotrack-player-shell');document.dispatchEvent(new CustomEvent('videotrack:playstate',{detail:{playing:!!playing}}));if(!root){return;}var hint=document.getElementById('videotrack-reactions-hint');root.querySelectorAll('.videotrack-reaction-btn').forEach(function(button){button.removeAttribute('disabled');button.setAttribute('aria-disabled',playing?'false':'true');if(hint&&hint.id){button.setAttribute('aria-describedby',hint.id);}button.classList.toggle('videotrack-reaction-disabled',!playing);});}function isSafeIconSrc(value){if(!value){return false;}var trimmed=String(value).replace(/[\u0000-\u001f\u007f]/g,'').trim();var lower=trimmed.toLowerCase();if(lower.indexOf('javascript:')===0||lower.indexOf('data:')===0||lower.indexOf('vbscript:')===0){return false;}try{var url=new URL(trimmed,window.location.origin);if(url.origin!==window.location.origin||url.username||url.password||url.hash){return false;}var path=decodeURIComponent(url.pathname).replace(/\\/g,'/').replace(/\/+/g,'/');if(/(?:^|\/)\.\.(?:\/|$)/.test(path)){return false;}if(!/\.(?:jpe?g|png|gif|webp)$/i.test(path)){return false;}return path.indexOf('/pluginfile.php/')!==-1||path.indexOf('/webservice/pluginfile.php/')!==-1;}catch(e){return false;}}function isSafeIconClass(value){if(!value){return false;}var parts=String(value).trim().split(/\s+/);if(parts.length===0||parts.length>4||parts.some(function(part){return part.length>48;})){return false;}var hasIconName=parts.some(function(part){return/^fa-[a-z0-9-]+$/.test(part);});return hasIconName&&parts.every(function(part){return/^(fa|fas|far|fab|fa-[a-z0-9-]+)$/.test(part);});}function appendIconSafe(target,icon){if(!target||!icon){return;}if(typeof icon==='string'){var legacy=String(icon).replace(/[\u0000-\u001f\u007f]/g,'').trim();if(legacy===''){return;}if(legacy.length>64){legacy=legacy.substring(0,64);}target.appendChild(document.createTextNode(legacy));return;}var type=String(icon.type||'emoji');if(['emoji','file','fa','text'].indexOf(type)===-1){return;}if(type==='file'&&isSafeIconSrc(icon.src)){var img=document.createElement('img');img.setAttribute('src',String(icon.src));img.setAttribute('alt','');img.setAttribute('aria-hidden','true');img.className='videotrack-reaction-icon-file';target.appendChild(img);return;}if(type==='fa'&&isSafeIconClass(icon.iconclass)){var fa=document.createElement('i');fa.className=String(icon.iconclass).trim();fa.setAttribute('aria-hidden','true');target.appendChild(fa);return;}var text=String(icon.text||'').trim();if(text.length>64){text=text.substring(0,64);}if(text!==''){var span=document.createElement('span');span.className='videotrack-reaction-icon-text';span.textContent=text;target.appendChild(span);}}return{setReactionButtons:setReactionButtons,appendIconSafe:appendIconSafe};});
